mapper.select:
SELECT id, order_no FROM order_info
WHERE status='PENDING_PAYMENT' AND payment_prepared_amount IS NOT NULL AND id > #{afterId}
ORDER BY id LIMIT #{size}

SELECT o.order_no FROM order_info o LEFT JOIN
        order_inventory_confirmation i ON o.order_no=i.order_no WHERE o.status='PAID' AND i.order_no IS NULL ORDER BY
        o.id LIMIT #{size}
